// 1) Simple standalone demo of new sizes
import React from 'react';
import ReactDOM from 'react-dom';
import { Button } from 'carbon-components-react';

function SizeDemo() {
  return (
    <div style={{ display: 'flex', gap: '1rem', alignItems: 'flex-end' }}>
      <div>
        <p>default (40px)</p>
        <Button kind="primary">Default</Button>
      </div>
      <div>
        <p>large (64px / 8rem)</p>
        <Button kind="primary" size="large">Large</Button>
      </div>
      <div>
        <p>xl (80px / 10rem)</p>
        <Button kind="primary" size="xl">XL</Button>
      </div>
    </div>
  );
}

ReactDOM.render(<SizeDemo />, document.getElementById('root'));

// 2) Repro in a modal footer
import {
  ComposedModal,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button as CarbonButton,
} from 'carbon-components-react';

function ModalWithXlButtons() {
  const [open, setOpen] = React.useState(false);
  return (
    <>
      <CarbonButton kind="primary" onClick={() => setOpen(true)}>
        Open modal
      </CarbonButton>
      {typeof document !== 'undefined' &&
        ReactDOM.createPortal(
          <ComposedModal open={open} onClose={() => setOpen(false)} size="lg">
            <ModalHeader>Example modal</ModalHeader>
            <ModalBody>
              <p>Modal body content here</p>
            </ModalBody>
            {/* Passing size to each Button in the footer */}
            <ModalFooter>
              <CarbonButton kind="secondary" size="large" onClick={() => setOpen(false)}>
                Previous
              </CarbonButton>
              <CarbonButton kind="primary" size="xl" onClick={() => setOpen(false)}>
                Next
              </CarbonButton>
            </ModalFooter>
          </ComposedModal>,
          document.body
        )}
    </>
  );
}

ReactDOM.render(<ModalWithXlButtons />, document.getElementById('modal-root'));
